# IES Training - MikroTik - L1 - Foto de fabrica
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
# Solo lee y guarda un export: no toca la configuracion.
{
:local archivo "{{ARCHIVO}}"
:put "== Listas de interfaces (WAN y LAN) =="
/interface/list/member/print
:put "== Direcciones IP =="
/ip/address/print
:put ("Reglas de firewall filter: " . [:len [/ip/firewall/filter/find]])
:if ([:len [/ip/firewall/filter/find comment="defconf: drop all not coming from LAN"]] > 0) do={
  :put "OK: esta el drop de fabrica que protege al router (input)."
} else={
  :put "Ojo: no esta el drop de fabrica. Equipo sin defconf (CCR) o firewall reescrito."
}
:if ([:len [/interface/list/find name=LAN]] = 0) do={
  :put "Ojo: no existe la lista LAN. Antes de seguir, crearla con el bridge adentro."
}
# El export inicial es la foto del primer dia: si ya existe, no se pisa
:if ([:len [/file/find where name~$archivo]] = 0) do={
  /export file=$archivo
  :put ("Export guardado: " . $archivo . ".rsc")
} else={
  :put ("Ya habia un " . $archivo . ".rsc: no lo piso.")
}
:put ("Listo: revisado lo de fabrica y foto en " . $archivo . ".rsc. Verifica con /file/print")
}

# IES Training - MikroTik - L2 - Usuarios propios
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local usuario "{{USUARIO}}"
:local clave "{{CLAVE}}"
:local mesa "{{USUARIO_MESA}}"
:local claveMesa "{{CLAVE_MESA}}"
:local red "{{RED_GESTION}}"
# Tu usuario con grupo full (si ya existe, no se toca su clave)
:if ([:len [/user/find name=$usuario]] = 0) do={
  /user/add name=$usuario group=full password=$clave comment="ies-usuario-tecnico"
  :put ("Creado " . $usuario)
} else={ :put ("Ya existia " . $usuario . ": no cambio su clave") }
# Grupo para mirar sin tocar: sin reboot ni write
:if ([:len [/user/group/find name=monitoreo]] = 0) do={
  /user/group/add name=monitoreo policy=local,ssh,winbox,read,test
} else={ /user/group/set [find name=monitoreo] policy=local,ssh,winbox,read,test }
# Mesa de ayuda: grupo monitoreo y solo desde la red de gestion
:if ([:len [/user/find name=$mesa]] = 0) do={
  /user/add name=$mesa group=monitoreo password=$claveMesa address=$red comment="ies-usuario-mesa"
  :put ("Creado " . $mesa)
} else={ /user/set [find name=$mesa] group=monitoreo address=$red }
# Deshabilitar admin: SOLO despues de entrar con tu usuario en otra sesion.
# Si tu usuario no anda y admin queda deshabilitado, la salida es reset o Netinstall.
# /user/disable [find name=admin]
:put ("Listo: " . $usuario . " (full) y " . $mesa . " (monitoreo). Proba entrar con " . $usuario . " y despues deshabilita admin a mano.")
/user/print
}

# IES Training - MikroTik - Un bridge con sus puertos y la IP en el bridge
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
:local bridge "{{BRIDGE}}"
:local puertos [:toarray "{{PUERTOS}}"]
:local lanip "{{LAN_IP}}"
# 1. El bridge, con MAC fija para que no cambie al sacar un puerto
:if ([:len [/interface/bridge/find name=$bridge]] = 0) do={
  :local mac [/interface/ethernet/get [find name=[:pick $puertos 0]] mac-address]
  /interface/bridge/add name=$bridge auto-mac=no admin-mac=$mac comment="ies-bridge"
  :put ("Bridge " . $bridge . " creado con admin-mac " . $mac)
} else={
  :if ([/interface/bridge/get [find name=$bridge] auto-mac]) do={
    :local mac [/interface/bridge/get [find name=$bridge] mac-address]
    /interface/bridge/set [find name=$bridge] auto-mac=no admin-mac=$mac
    :put ("admin-mac fijada en " . $mac)
  }
}
# 2. Puertos al bridge: salteo los que ya estan en un bridge, los WAN y los que tienen IP
:foreach p in=$puertos do={
  :if ([:len [/interface/bridge/port/find interface=$p]] > 0) do={
    :put ($p . " ya esta en un bridge: no lo toco")
  } else={
    :local esWan false
    :if ([:len [/interface/list/find name=WAN]] > 0) do={ :set esWan ([:len [/interface/list/member/find list=WAN interface=$p]] > 0) }
    :if ($esWan || ([:len [/ip/address/find interface=$p]] > 0)) do={
      :put ($p . " es WAN o tiene IP propia: lo salteo")
    } else={
      /interface/bridge/port/add bridge=$bridge interface=$p comment="ies-bridge"
      :put ($p . " agregado a " . $bridge)
    }
  }
}
# 3. La IP de la LAN va en el bridge, nunca en un puerto
:if ([:len [/ip/address/find interface=$bridge address=$lanip]] = 0) do={
  /ip/address/add address=$lanip interface=$bridge comment="ies-bridge"
  :put ("IP " . $lanip . " cargada en " . $bridge)
}
# 4. (Opcional, comentado) ether1 como WAN si vino dentro del bridge.
#    Ojo: si entras por ether1, te corta. Hacelo desde otro puerto.
# /interface/bridge/port/remove [find interface=ether1]
# /interface/list/member/add list=WAN interface=ether1
# /ip/dhcp-client/add interface=ether1 disabled=no
:put ("Listo: bridge " . $bridge . " con sus puertos y la IP " . $lanip . ". Verifica la marca H con /interface/bridge/port/print")

# IES Training - MikroTik - Red nueva con IP y servidor DHCP
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
:local iface "{{INTERFAZ}}"
:local nombre "{{NOMBRE}}"
:local ipr "{{IP_ROUTER}}"
:local red "{{RED}}"
:local gw "{{GATEWAY}}"
:local rango "{{RANGO}}"
:local pool ("pool-" . $nombre)
:local srv ("dhcp-" . $nombre)
# 0. La IP no va en un puerto de bridge: si lo esta, freno aca
:if ([:len [/interface/bridge/port/find interface=$iface]] > 0) do={
  :put ($iface . " esta dentro de un bridge. Sacalo primero (y no desde ese mismo puerto):")
  :put ("/interface/bridge/port/remove [find interface=" . $iface . "]")
  :error "detenido: puerto dentro de un bridge"
}
# 1. IP del router en la interfaz
:if ([:len [/ip/address/find interface=$iface address=$ipr]] = 0) do={
  /ip/address/add address=$ipr interface=$iface comment=("ies-" . $nombre)
}
# 2. En la lista LAN, para que el router le conteste DNS y WinBox
:if ([:len [/interface/list/find name=LAN]] > 0) do={
  :if ([:len [/interface/list/member/find list=LAN interface=$iface]] = 0) do={
    /interface/list/member/add list=LAN interface=$iface comment=("ies-" . $nombre)
  }
}
# 3. Pool (sin la IP del router)
:if ([:len [/ip/pool/find name=$pool]] = 0) do={
  /ip/pool/add name=$pool ranges=$rango comment=("ies-" . $nombre)
} else={ /ip/pool/set [find name=$pool] ranges=$rango }
# 4. Red: gateway y DNS que reciben los equipos
:if ([:len [/ip/dhcp-server/network/find address=$red]] = 0) do={
  /ip/dhcp-server/network/add address=$red gateway=$gw dns-server=$gw comment=("ies-" . $nombre)
} else={ /ip/dhcp-server/network/set [find address=$red] gateway=$gw dns-server=$gw }
# 5. El servidor, que une interfaz y pool
:if ([:len [/ip/dhcp-server/find name=$srv]] = 0) do={
  /ip/dhcp-server/add name=$srv interface=$iface address-pool=$pool disabled=no comment=("ies-" . $nombre)
} else={ /ip/dhcp-server/set [find name=$srv] interface=$iface address-pool=$pool disabled=no }
:put ("Listo: " . $ipr . " en " . $iface . " con DHCP " . $srv . " (" . $rango . "). Verifica con /ip/dhcp-server/lease/print where server=" . $srv)

# IES Training - MikroTik - Leccion 14: Cliente DHCP en la WAN
# Probalo primero en un equipo de banco. Si es la unica WAN y entras por ella, en Safe Mode (Ctrl+X).
{
  :local wan "{{WAN}}"
  :local dist {{DISTANCIA}}
  :local c [/ip/dhcp-client/find interface=$wan]
  :if ([:len $c] = 0) do={
    # No hay cliente: se crea solo si la interfaz no tiene IP fija, para que no compitan
    :if ([:len [/ip/address/find interface=$wan dynamic=no]] > 0) do={ :error "La WAN tiene IP fija: sacala antes (leccion 13)" }
    /ip/dhcp-client/add interface=$wan add-default-route=yes use-peer-dns=yes use-peer-ntp=yes default-route-distance=$dist comment="ies-dhcp-wan" disabled=no
    :set c [/ip/dhcp-client/find interface=$wan]
  } else={
    /ip/dhcp-client/set $c default-route-distance=$dist disabled=no
  }
  # 3. Lease nuevo sin esperar
  /ip/dhcp-client/renew $c
  :delay 5s
  # 1. Lo que recibio
  :local st [:tostr [/ip/dhcp-client/get $c status]]
  :local addr [:tostr [/ip/dhcp-client/get $c address]]
  :put ("status=" . $st . " address=" . $addr . " gateway=" . [/ip/dhcp-client/get $c gateway])
  :put ("primary-dns=" . [/ip/dhcp-client/get $c primary-dns] . " primary-ntp=" . [/ip/dhcp-client/get $c primary-ntp])
  :if ($st != "bound") do={ :put "Todavia no esta bound: revisa cable y modem, y /log/print where topics~\"dhcp\"" }
  # 4. Doble NAT o CGNAT: lo dice la IP recibida
  :if ([:len $addr] > 0) do={
    :local ip [:toip [:pick $addr 0 [:find $addr "/"]]]
    :if (($ip in 10.0.0.0/8) || ($ip in 172.16.0.0/12) || ($ip in 192.168.0.0/16)) do={ :put "IP privada: hay otro NAT adelante (modem en modo router)." }
    :if ($ip in 100.64.0.0/10) do={ :put "IP en 100.64.0.0/10: CGNAT, sin acceso entrante (leccion 9)." }
  }
  /ip/route/print where dst-address=0.0.0.0/0
  :put ("Listo: cliente DHCP en " . $wan . " con distancia " . $dist . ". Verifica: /ip/cloud/print (public-address)")
}

# IES Training - MikroTik - Leccion 13: IP fija en la WAN
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X): un gateway mal escrito te deja afuera.
{
  :local wan "{{WAN}}"
  :local ip "{{WAN_IP}}"
  :local gw [:toip "{{GATEWAY}}"]
  # Foto de antes (leccion 6)
  /export file=ies-antes-ip-fija
  # 1. El cliente DHCP de la WAN se apaga para que no compita
  /ip/dhcp-client/disable [find interface=$wan]
  # 2. Direccion: si ya esta (por comentario o por IP), se corrige; si no, se agrega
  :local a [/ip/address/find where comment="ies-WAN fija"]
  :if ([:len $a] = 0) do={ :set a [/ip/address/find where address=$ip interface=$wan] }
  :if ([:len $a] = 0) do={ /ip/address/add address=$ip interface=$wan comment="ies-WAN fija" } else={ /ip/address/set $a address=$ip interface=$wan comment="ies-WAN fija" }
  :local r [/ip/route/find where comment="ies-default WAN fija"]
  :if ([:len $r] = 0) do={ /ip/route/add dst-address=0.0.0.0/0 gateway=$gw comment="ies-default WAN fija" } else={ /ip/route/set $r gateway=$gw }
  /ip/dns/set servers={{DNS}}
  # 3. Verificar por capas
  :delay 2s
  :local p1 [/ping $gw count=3]
  :local p2 [/ping 1.1.1.1 count=3]
  :local nombre "sin resolver"
  :do { :set nombre [:tostr [:resolve mikrotik.com]] } on-error={}
  :put ("Gateway " . $gw . ": " . $p1 . "/3 | Internet 1.1.1.1: " . $p2 . "/3 | mikrotik.com: " . $nombre)
  :if ($p1 = 0) do={ :put "Gateway sin respuesta: cable, mascara o VLAN." }
  :if ($p1 > 0 && $p2 = 0) do={ :put "Internet sin respuesta: ruta o proveedor." }
  :if ($p2 > 0 && $nombre = "sin resolver") do={ :put "Nombre sin resolver: DNS." }
  # 4. IP directa: public-address de IP Cloud tiene que ser la misma IP (con DDNS activo)
  :local pub ""
  :do { :set pub [:tostr [/ip/cloud/get public-address]] } on-error={}
  :put ("public-address: " . $pub . " | IP WAN: " . [:pick $ip 0 [:find $ip "/"]])
  :put "Listo: WAN fija con direccion, ruta y DNS. Anota en el legajo IP, mascara, gateway, DNS y quien los entrego."
  :put "Verifica: /ip/route/print where dst-address=0.0.0.0/0"
}

# IES Training - MikroTik - Leccion 15: PPPoE con Antel
# Con el ONT ya en puente. El sitio queda sin internet hasta que el PPPoE marque: coordina la ventana.
{
  :local wan "{{WAN}}"
  :local nombre "{{PPPOE}}"
  # Opcionales: VLAN vacia salvo que Antel confirme un numero; MTU vacio = lo que negocie
  :local vlan "{{VLAN_ID}}"
  :local mtu "{{MTU}}"
  /export file=ies-antes-pppoe
  /ip/dhcp-client/disable [find interface=$wan]
  :if ([:len [/ip/address/find interface=$wan dynamic=no]] > 0) do={ :put "Ojo: la WAN tiene IP estatica. La documentacion desaconseja IP y PPPoE en la misma interfaz." }
  # 3. Con VLAN confirmada, el PPPoE va sobre la VLAN
  :local base $wan
  :if ([:len $vlan] > 0) do={
    :if ([:len [/interface/vlan/find name="vlan-wan"]] = 0) do={ /interface/vlan/add name=vlan-wan interface=$wan vlan-id=[:tonum $vlan] comment="ies-vlan-wan" } else={ /interface/vlan/set [find name="vlan-wan"] interface=$wan vlan-id=[:tonum $vlan] }
    :set base "vlan-wan"
  }
  # 2. Cliente PPPoE
  :local p [/interface/pppoe-client/find name=$nombre]
  :if ([:len $p] = 0) do={
    /interface/pppoe-client/add name=$nombre interface=$base user="{{USUARIO}}" password="{{CLAVE}}" add-default-route=yes use-peer-dns=yes comment="ies-pppoe-antel" disabled=no
  } else={
    /interface/pppoe-client/set $p interface=$base user="{{USUARIO}}" password="{{CLAVE}}" add-default-route=yes use-peer-dns=yes disabled=no
  }
  :if ([:len $mtu] > 0) do={ /interface/pppoe-client/set [find name=$nombre] max-mtu=[:tonum $mtu] max-mru=[:tonum $mtu] }
  # La WAN pasa a ser el PPPoE: masquerade y reglas por la lista WAN
  :if ([:len [/interface/list/find name=WAN]] = 0) do={ /interface/list/add name=WAN comment="ies-pppoe-antel" }
  :if ([:len [/interface/list/member/find list=WAN interface=$nombre]] = 0) do={ /interface/list/member/add list=WAN interface=$nombre comment="ies-pppoe-antel" }
  # 5. MSS: si el perfil PPP no lo ajusta, regla de mangle
  :local perfil [/interface/pppoe-client/get [find name=$nombre] profile]
  :local mss [:tostr [/ppp/profile/get [find name=$perfil] change-tcp-mss]]
  :if ($mss != "yes" && $mss != "true" && [:len [/ip/firewall/mangle/find comment="ies-MSS PPPoE"]] = 0) do={
    /ip/firewall/mangle/add chain=forward out-interface=$nombre protocol=tcp tcp-flags=syn action=change-mss new-mss=clamp-to-pmtu passthrough=yes comment="ies-MSS PPPoE"
  }
  # 4. Estado y MTU negociado
  :delay 10s
  /interface/pppoe-client/monitor [find name=$nombre] once
  :put ("Listo: PPPoE " . $nombre . " sobre " . $base . ", en la lista WAN y con MSS cubierto. Anota status, mtu, mru y local-address.")
  :put "Verifica: /ip/route/print where dst-address=0.0.0.0/0 ; /ping 1.1.1.1 count=3"
}

# IES Training - MikroTik - Dos WAN con failover por rutas recursivas
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X). Antes, un export.
:local wan1 "{{WAN1_IF}}"
:local wan2 "{{WAN2_IF}}"
:local gw1 "{{GW1}}"
:local gw2 "{{GW2}}"
:local t1a "{{TESTIGO1_A}}"
:local t1b "{{TESTIGO1_B}}"
:local t2a "{{TESTIGO2_A}}"
:local t2b "{{TESTIGO2_B}}"
:local dns "{{DNS}}"
# Testigos: una /32 por su proveedor (scope=10)
:if ([:len [/ip/route/find where comment="ies-testigo-isp1-a"]] = 0) do={/ip/route/add dst-address=$t1a gateway=$gw1 scope=10 comment="ies-testigo-isp1-a"} else={/ip/route/set [find where comment="ies-testigo-isp1-a"] dst-address=$t1a gateway=$gw1 scope=10}
:if ([:len [/ip/route/find where comment="ies-testigo-isp1-b"]] = 0) do={/ip/route/add dst-address=$t1b gateway=$gw1 scope=10 comment="ies-testigo-isp1-b"} else={/ip/route/set [find where comment="ies-testigo-isp1-b"] dst-address=$t1b gateway=$gw1 scope=10}
:if ([:len [/ip/route/find where comment="ies-testigo-isp2-a"]] = 0) do={/ip/route/add dst-address=$t2a gateway=$gw2 scope=10 comment="ies-testigo-isp2-a"} else={/ip/route/set [find where comment="ies-testigo-isp2-a"] dst-address=$t2a gateway=$gw2 scope=10}
:if ([:len [/ip/route/find where comment="ies-testigo-isp2-b"]] = 0) do={/ip/route/add dst-address=$t2b gateway=$gw2 scope=10 comment="ies-testigo-isp2-b"} else={/ip/route/set [find where comment="ies-testigo-isp2-b"] dst-address=$t2b gateway=$gw2 scope=10}
# Rutas por defecto recursivas: ISP1 distancia 1, ISP2 distancia 2
:if ([:len [/ip/route/find where comment="ies-default-isp1-a"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t1a target-scope=11 check-gateway=ping distance=1 comment="ies-default-isp1-a"} else={/ip/route/set [find where comment="ies-default-isp1-a"] dst-address=0.0.0.0/0 gateway=$t1a target-scope=11 check-gateway=ping distance=1}
:if ([:len [/ip/route/find where comment="ies-default-isp1-b"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t1b target-scope=11 check-gateway=ping distance=1 comment="ies-default-isp1-b"} else={/ip/route/set [find where comment="ies-default-isp1-b"] dst-address=0.0.0.0/0 gateway=$t1b target-scope=11 check-gateway=ping distance=1}
:if ([:len [/ip/route/find where comment="ies-default-isp2-a"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t2a target-scope=11 check-gateway=ping distance=2 comment="ies-default-isp2-a"} else={/ip/route/set [find where comment="ies-default-isp2-a"] dst-address=0.0.0.0/0 gateway=$t2a target-scope=11 check-gateway=ping distance=2}
:if ([:len [/ip/route/find where comment="ies-default-isp2-b"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t2b target-scope=11 check-gateway=ping distance=2 comment="ies-default-isp2-b"} else={/ip/route/set [find where comment="ies-default-isp2-b"] dst-address=0.0.0.0/0 gateway=$t2b target-scope=11 check-gateway=ping distance=2}
# Las rutas por defecto comunes a esos gateways compiten: se apagan, no se borran
/ip/route/disable [find where static and dst-address=0.0.0.0/0 and (gateway=$gw1 or gateway=$gw2)]
# Las dos salidas en la lista WAN, para el masquerade de fabrica
:foreach i in={$wan1;$wan2} do={:if ([:len [/interface/list/member/find where list=WAN and interface=$i]] = 0) do={/interface/list/member/add list=WAN interface=$i comment="ies-dos-wan"}}
# DNS del router que no sean testigos
/ip/dns/set servers=[:toarray $dns]
# Clientes DHCP o PPPoE que meten su propia ruta con distancia baja
:foreach c in=[/ip/dhcp-client/find where disabled=no and add-default-route=yes and default-route-distance<3] do={:put ("Ojo: el cliente DHCP de " . [/ip/dhcp-client/get $c interface] . " instala su ruta por defecto con distancia baja")}
:foreach c in=[/interface/pppoe-client/find where disabled=no and add-default-route=yes and default-route-distance<3] do={:put ("Ojo: el PPPoE " . [/interface/pppoe-client/get $c name] . " instala su ruta por defecto con distancia baja")}
:put "Listo: testigos, recursivas con distancias 1 y 2, lista WAN y DNS. Verifica con /ip/route/print where dst-address=0.0.0.0/0"

# IES Training - MikroTik - Dos WAN: IP fija principal + PPPoE de respaldo
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X). Antes, un export.
:local wanF "{{WAN_FIJA_IF}}"
:local ipF "{{IP_FIJA}}"
:local gwF "{{GW_FIJA}}"
:local wanP "{{WAN_PPPOE_IF}}"
:local pp "{{PPPOE_NOMBRE}}"
:local usuario "{{PPPOE_USUARIO}}"
:local clave "{{PPPOE_CLAVE}}"
:local t1 "{{TESTIGO_A}}"
:local t2 "{{TESTIGO_B}}"
:local dns "{{DNS}}"
:if ([:len [/interface/bridge/port/find where interface=$wanP]] > 0) do={:put ("Ojo: " . $wanP . " esta en el bridge. Si no entras por ese puerto, sacalo con /interface/bridge/port/remove [find interface=" . $wanP . "]")}
# IP fija en su puerto (si ya estaba, sigue de largo) y sin cliente DHCP ahi
/ip/dhcp-client/disable [find where interface=$wanF]
:do {/ip/address/add address=$ipF interface=$wanF comment="ies-ip-fija"} on-error={:put "La IP fija ya estaba cargada"}
# Testigos por el gateway de la fija y recursivas en distancia 1
:if ([:len [/ip/route/find where comment="ies-testigo-fija-a"]] = 0) do={/ip/route/add dst-address=$t1 gateway=$gwF scope=10 comment="ies-testigo-fija-a"} else={/ip/route/set [find where comment="ies-testigo-fija-a"] dst-address=$t1 gateway=$gwF scope=10}
:if ([:len [/ip/route/find where comment="ies-testigo-fija-b"]] = 0) do={/ip/route/add dst-address=$t2 gateway=$gwF scope=10 comment="ies-testigo-fija-b"} else={/ip/route/set [find where comment="ies-testigo-fija-b"] dst-address=$t2 gateway=$gwF scope=10}
:if ([:len [/ip/route/find where comment="ies-default-fija-a"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t1 target-scope=11 check-gateway=ping distance=1 comment="ies-default-fija-a"} else={/ip/route/set [find where comment="ies-default-fija-a"] dst-address=0.0.0.0/0 gateway=$t1 target-scope=11 check-gateway=ping distance=1}
:if ([:len [/ip/route/find where comment="ies-default-fija-b"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t2 target-scope=11 check-gateway=ping distance=1 comment="ies-default-fija-b"} else={/ip/route/set [find where comment="ies-default-fija-b"] dst-address=0.0.0.0/0 gateway=$t2 target-scope=11 check-gateway=ping distance=1}
/ip/route/disable [find where static and dst-address=0.0.0.0/0 and gateway=$gwF]
# PPPoE de respaldo con su ruta en distancia 2 y sin sus DNS
:if ([:len [/interface/pppoe-client/find where name=$pp]] = 0) do={/interface/pppoe-client/add name=$pp interface=$wanP user=$usuario password=$clave add-default-route=yes default-route-distance=2 use-peer-dns=no max-mtu=1492 max-mru=1492 disabled=no comment="ies-wan2"} else={/interface/pppoe-client/set [find where name=$pp] interface=$wanP user=$usuario password=$clave add-default-route=yes default-route-distance=2 use-peer-dns=no}
:foreach i in={$wanF;$pp} do={:if ([:len [/interface/list/member/find where list=WAN and interface=$i]] = 0) do={/interface/list/member/add list=WAN interface=$i comment="ies-dos-wan"}}
:if ([:len [/ip/firewall/mangle/find where comment="ies-mss-pppoe"]] = 0) do={/ip/firewall/mangle/add chain=forward out-interface=$pp protocol=tcp tcp-flags=syn action=change-mss new-mss=clamp-to-pmtu passthrough=yes comment="ies-mss-pppoe"}
/ip/dns/set servers=[:toarray $dns]
# Lo que entra por la IP fija responde por la IP fija, sea cual sea el principal
:if ([:len [/routing/table/find where name="por-fija"]] = 0) do={/routing/table/add name=por-fija fib}
:if ([:len [/ip/route/find where comment="ies-tabla-fija"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=($gwF . "@main") routing-table=por-fija comment="ies-tabla-fija"}
:if ([:len [/ip/firewall/mangle/find where comment="ies-entra-fija"]] = 0) do={
/ip/firewall/mangle/add chain=prerouting in-interface=$wanF connection-state=new action=mark-connection new-connection-mark=entra-fija comment="ies-entra-fija"
/ip/firewall/mangle/add chain=prerouting in-interface-list=LAN connection-mark=entra-fija action=mark-routing new-routing-mark=por-fija comment="ies-entra-fija"
/ip/firewall/mangle/add chain=output connection-mark=entra-fija action=mark-routing new-routing-mark=por-fija comment="ies-entra-fija"
}
# FastTrack solo usa la tabla main: que no agarre lo marcado
/ip/firewall/filter/set [find where action=fasttrack-connection] connection-mark=no-mark
:put ("Listo: " . $wanF . " principal con recursivas, " . $pp . " de respaldo en distancia 2 y respuestas por la fija. Verifica con /ip/firewall/mangle/print stats where comment=\"ies-entra-fija\"")

# IES Training - MikroTik - Dos WAN: IP fija principal + DHCP (4G) de respaldo
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X). Antes, un export.
:local wanF "{{WAN_FIJA_IF}}"
:local gwF "{{GW_FIJA}}"
:local wanD "{{WAN_DHCP_IF}}"
:local gw4 "{{GW_4G}}"
:local t1 "{{TESTIGO_A}}"
:local t2 "{{TESTIGO_B}}"
:local dns "{{DNS}}"
:local balancear "{{BALANCEAR}}"
:local locales "{{NO_BALANCEAR}}"
:if ([:len [/interface/bridge/port/find where interface=$wanD]] > 0) do={:put ("Ojo: " . $wanD . " esta en el bridge. Si no entras por ese puerto, sacalo con /interface/bridge/port/remove [find interface=" . $wanD . "]")}
# Recursivas por la IP fija (la IP ya cargada como en la leccion de IP fija)
:if ([:len [/ip/route/find where comment="ies-testigo-fija-a"]] = 0) do={/ip/route/add dst-address=$t1 gateway=$gwF scope=10 comment="ies-testigo-fija-a"} else={/ip/route/set [find where comment="ies-testigo-fija-a"] dst-address=$t1 gateway=$gwF scope=10}
:if ([:len [/ip/route/find where comment="ies-testigo-fija-b"]] = 0) do={/ip/route/add dst-address=$t2 gateway=$gwF scope=10 comment="ies-testigo-fija-b"} else={/ip/route/set [find where comment="ies-testigo-fija-b"] dst-address=$t2 gateway=$gwF scope=10}
:if ([:len [/ip/route/find where comment="ies-default-fija-a"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t1 target-scope=11 check-gateway=ping distance=1 comment="ies-default-fija-a"} else={/ip/route/set [find where comment="ies-default-fija-a"] dst-address=0.0.0.0/0 gateway=$t1 target-scope=11 check-gateway=ping distance=1}
:if ([:len [/ip/route/find where comment="ies-default-fija-b"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=$t2 target-scope=11 check-gateway=ping distance=1 comment="ies-default-fija-b"} else={/ip/route/set [find where comment="ies-default-fija-b"] dst-address=0.0.0.0/0 gateway=$t2 target-scope=11 check-gateway=ping distance=1}
/ip/route/disable [find where static and dst-address=0.0.0.0/0 and gateway=$gwF]
# DHCP del 4G de respaldo: distancia 2, sin sus DNS ni NTP
:if ([:len [/ip/dhcp-client/find where interface=$wanD]] = 0) do={/ip/dhcp-client/add interface=$wanD add-default-route=yes default-route-distance=2 use-peer-dns=no use-peer-ntp=no disabled=no comment="ies-wan2"} else={/ip/dhcp-client/set [find where interface=$wanD] add-default-route=yes default-route-distance=2 use-peer-dns=no use-peer-ntp=no disabled=no}
:foreach i in={$wanF;$wanD} do={:if ([:len [/interface/list/member/find where list=WAN and interface=$i]] = 0) do={/interface/list/member/add list=WAN interface=$i comment="ies-dos-wan"}}
/ip/dns/set servers=[:toarray $dns]
# Balanceo PCC: solo si BALANCEAR es "si" y el 4G no tiene tope de datos
:if ($balancear = "si") do={
:foreach t in={"por-fija";"por-4g"} do={:if ([:len [/routing/table/find where name=$t]] = 0) do={/routing/table/add name=$t fib}}
:if ([:len [/ip/route/find where comment="ies-pcc-fija"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=($gwF . "@main") routing-table=por-fija check-gateway=ping comment="ies-pcc-fija"}
:if ([:len [/ip/route/find where comment="ies-pcc-4g"]] = 0) do={/ip/route/add dst-address=0.0.0.0/0 gateway=($gw4 . "@main") routing-table=por-4g check-gateway=ping comment="ies-pcc-4g"}
:foreach n in=[:toarray $locales] do={:do {/ip/firewall/address-list/add list=no-balancear address=$n comment="ies-pcc"} on-error={}}
:if ([:len [/ip/firewall/mangle/find where comment="ies-pcc"]] = 0) do={
/ip/firewall/mangle/add chain=prerouting in-interface-list=LAN dst-address-list=no-balancear action=accept comment="ies-pcc"
/ip/firewall/mangle/add chain=prerouting in-interface-list=LAN dst-address-type=!local connection-state=new connection-mark=no-mark per-connection-classifier=both-addresses:2/0 action=mark-connection new-connection-mark=pcc-fija comment="ies-pcc"
/ip/firewall/mangle/add chain=prerouting in-interface-list=LAN dst-address-type=!local connection-state=new connection-mark=no-mark per-connection-classifier=both-addresses:2/1 action=mark-connection new-connection-mark=pcc-4g comment="ies-pcc"
/ip/firewall/mangle/add chain=prerouting in-interface-list=LAN connection-mark=pcc-fija action=mark-routing new-routing-mark=por-fija comment="ies-pcc"
/ip/firewall/mangle/add chain=prerouting in-interface-list=LAN connection-mark=pcc-4g action=mark-routing new-routing-mark=por-4g comment="ies-pcc"
}
/ip/firewall/filter/set [find where action=fasttrack-connection] connection-mark=no-mark
}
:put ("Listo: " . $wanF . " principal con recursivas y " . $wanD . " de respaldo en distancia 2, balanceo: " . $balancear . ". Verifica con /ip/route/print where dst-address=0.0.0.0/0")

# IES Training - MikroTik - L29 - Chequeo de conectividad en escalera
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
# Solo lee y pingea: no toca la configuracion.
{
:local host "{{LAN_HOST}}"
:local lanif "{{LAN_IF}}"
:local lanip "{{LAN_IP_ROUTER}}"
:local ipnet "{{IP_INTERNET}}"
:local nombre "{{NOMBRE}}"
:local falla "ninguna"
# 1. LAN (si no contesta ping, probamos ARP)
:local r1 [/ping $host count=3]
:if ($r1 = 0) do={
  :local a [/ping $host arp-ping=yes interface=$lanif count=2]
  :if ($a = 0) do={ :set falla "1 LAN: cable, puerto o bridge" } else={ :put "El equipo contesta ARP: esta vivo, bloquea el ping." }
}
# 2. Gateway de la ruta por defecto activa
:local rt [/ip/route/find where dst-address=0.0.0.0/0 active]
:local gw ""
:if ([:len $rt] > 0) do={ :set gw [:tostr [/ip/route/get [:pick $rt 0] gateway]] }
:if ([:typeof [:toip $gw]] = "ip") do={
  :if (([/ping $gw count=3] = 0) and ($falla = "ninguna")) do={ :set falla "2 gateway: WAN, modem, VLAN o PPPoE" }
} else={ :put ("Gateway sin IP (" . $gw . "): escalon 2 salteado.") }
# 3. IP de internet
:if (([/ping $ipnet count=3] = 0) and ($falla = "ninguna")) do={ :set falla "3 internet: ruta por defecto o proveedor" }
# 4. Nombre (si no resuelve, ping corta el script: lo atajamos)
:do { :if (([/ping $nombre count=3] = 0) and ($falla = "ninguna")) do={ :set falla "4 nombre: sin respuesta" } } on-error={ :if ($falla = "ninguna") do={ :set falla "4 nombre: DNS (resolve failed)" } }
# 5. Desde la IP de la LAN: prueba el masquerade
:if ([/ping $ipnet src-address=$lanip count=3] = 0) do={ :put "Ojo: desde la IP de la LAN no hay respuesta. Revisar masquerade." }
# 6. MTU del camino, sin fragmentar
:local mtu 0
:foreach s in={1500;1492;1480;1450;1400} do={
  :if ($mtu = 0) do={ :if ([/ping $ipnet size=$s do-not-fragment count=2] > 0) do={ :set mtu $s } }
}
:put ("MTU del camino: " . $mtu . " (0 = ninguna probada paso)")
:put ("Listo: primera falla = " . $falla . ". Para ver los saltos: /tool/traceroute " . $ipnet . " count=3")
}

# IES Training - MikroTik - Vigilar con Netwatch (leccion 35)
# Probalo primero en un equipo de banco. No cambia firewall ni rutas.
{
:local nvr "{{NVR_IP}}"; :local puerto [:tonum "{{NVR_PUERTO}}"]; :local mail "{{MAIL_DESTINO}}"
:local smtp "{{SMTP_SERVIDOR}}"; :local usuario "{{SMTP_USUARIO}}"; :local clave "{{CLAVE}}"
:local token "{{TG_TOKEN}}"; :local chat "{{TG_CHAT}}"
:local cam "{{CAM_IP}}"; :local poe "{{CAM_PUERTO_POE}}"
# 1. Servidor de correo (587 + STARTTLS)
:if ([:len $smtp] > 0) do={
  /tool/e-mail/set server=$smtp port=587 tls=starttls from=$usuario user=$usuario password=$clave }
# 2. Scripts de aviso (texto sin tildes)
:local down (":log warning \"NVR " . $nvr . " caido\"; /tool/e-mail/send to=" . $mail . " subject=\"NVR caido\" body=\"El NVR " . $nvr . " no responde en el puerto " . $puerto . "\"")
:local up (":log info \"NVR " . $nvr . " volvio\"")
:if (([:len $token] > 0) && ([:len $chat] > 0)) do={
  :set up ($up . "; /tool/fetch mode=https address=api.telegram.org src-path=\"bot" . $token . "/sendMessage\3Fchat_id=" . $chat . "&text=NVR%20volvio\" check-certificate=yes output=none") }
# 3. Sonda al NVR: se crea o se actualiza
:local id [/tool/netwatch/find name="ies-nvr"]
:if ([:len $id] = 0) do={
  /tool/netwatch/add name="ies-nvr" comment="ies-netwatch" host=$nvr type=tcp-conn port=$puerto interval=30s down-script=$down up-script=$up
} else={
  /tool/netwatch/set $id host=$nvr type=tcp-conn port=$puerto interval=30s down-script=$down up-script=$up }
# 4. Camara PoE: corte de 10 s al caer (solo si cargaste CAM_IP)
:if ([:len $cam] > 0) do={
  :local ps ("/interface/ethernet/poe/power-cycle " . $poe . " duration=10s")
  :local idc [/tool/netwatch/find name="ies-camara"]
  :if ([:len $idc] = 0) do={
    /tool/netwatch/add name="ies-camara" comment="ies-netwatch" host=$cam type=icmp interval=1m down-script=$ps
  } else={ /tool/netwatch/set $idc host=$cam type=icmp interval=1m down-script=$ps } }
/tool/netwatch/print where comment="ies-netwatch"
:put "Listo: sondas ies-nvr (y ies-camara si la cargaste). Proba desenchufando y mira /log/print where message~\"NVR\""
}

# IES Training - MikroTik - Descubrir vecinos (leccion 34)
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local lista "{{LISTA}}"
:local puertos [:toarray "{{PUERTOS}}"]
:local proto "{{PROTOCOLOS}}"
:put "Antes:"
/ip/neighbor/discovery-settings/print
# Lista propia (si ya existe, se reutiliza)
:if ([:len [/interface/list/find name=$lista]] = 0) do={
  /interface/list/add name=$lista comment="ies-descubrir" }
:foreach p in=$puertos do={
  :if ([:len [/interface/find name=$p]] = 0) do={
    :put ("No existe la interfaz " . $p . ": la salteo")
  } else={
    :if ([:len [/interface/list/member/find list=$lista interface=$p]] = 0) do={
      /interface/list/member/add list=$lista interface=$p comment="ies-descubrir" } } }
# Sin puertos validos no se cambia nada
:if ([:len [/interface/list/member/find list=$lista]] = 0) do={ :error "La lista quedo vacia: revisa los nombres de los puertos" }
/ip/neighbor/discovery-settings/set discover-interface-list=$lista protocol=$proto
:put "Despues:"
/ip/neighbor/discovery-settings/print
/ip/neighbor/print
:put ("Listo: el router se anuncia solo en la lista " . $lista . ". Verifica desde la WAN con WinBox, pestana Neighbors.")
}

# IES Training - MikroTik - L5 - VLAN por sistema
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
# NO lo pegues conectado por el puerto de rescate: ese puerto sale del bridge.
{
:local br "{{BRIDGE}}"
:local acc "{{ACCESS}}"
:local trunk "{{TRUNK}}"
:local resc "{{RESCATE}}"
:local vc {{VLAN_CCTV}}
:local vg {{VLAN_GESTION}}
# 1. Puerto de rescate fuera del bridge, con IP propia
:if ([:len [/ip/address/find comment="ies-rescate"]] = 0) do={
  /interface/bridge/port/remove [find interface=$resc]
  /ip/address/add address={{IP_RESCATE}} interface=$resc comment="ies-rescate"
}
# 2. Puertos access (camaras) y trunk
:foreach p in=[:toarray $acc] do={
  /interface/bridge/port/set [find interface=$p] pvid=$vc frame-types=admit-only-untagged-and-priority-tagged ingress-filtering=yes
}
/interface/bridge/port/set [find interface=$trunk] frame-types=admit-only-vlan-tagged ingress-filtering=yes
# 3. Tabla VLAN: una entrada por VLAN; el bridge va tagged para que el router la vea
:if ([:len [/interface/bridge/vlan/find comment="ies-vlan-cctv"]] = 0) do={
  /interface/bridge/vlan/add bridge=$br tagged="$br,$trunk" untagged=$acc vlan-ids=$vc comment="ies-vlan-cctv"
}
:if ([:len [/interface/bridge/vlan/find comment="ies-vlan-gestion"]] = 0) do={
  /interface/bridge/vlan/add bridge=$br tagged="$br,$trunk" vlan-ids=$vg comment="ies-vlan-gestion"
}
# 4. Capa 3: interfaces vlan con su IP
:local ifc ("vlan" . $vc . "-cctv")
:local ifg ("vlan" . $vg . "-gestion")
:if ([:len [/interface/vlan/find name=$ifc]] = 0) do={ /interface/vlan/add name=$ifc interface=$br vlan-id=$vc comment="ies-vlan-cctv" }
:if ([:len [/interface/vlan/find name=$ifg]] = 0) do={ /interface/vlan/add name=$ifg interface=$br vlan-id=$vg comment="ies-vlan-gestion" }
:if ([:len [/ip/address/find comment="ies-ip-cctv"]] = 0) do={ /ip/address/add address={{IP_CCTV}} interface=$ifc comment="ies-ip-cctv" }
:if ([:len [/ip/address/find comment="ies-ip-gestion"]] = 0) do={ /ip/address/add address={{IP_GESTION}} interface=$ifg comment="ies-ip-gestion" }
/interface/bridge/vlan/print
# 5. Ultimo paso, A MANO y conectado por el puerto de rescate:
# /interface/bridge/set [find name="{{BRIDGE}}"] vlan-filtering=yes
:put ("Listo: VLAN " . $vc . " y " . $vg . " cargadas. Revisa la tabla y activa vlan-filtering desde " . $resc . ".")
}

# IES Training - MikroTik - L3 - Cerrar puertas
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local red {{RED_GESTION}}
# Antes de limitar: hay alguien conectado desde afuera de esa red
:local fuera 0
:foreach s in=[/user/active/find] do={
  :local a [:toip [/user/active/get $s address]]
  :if ([:typeof $a] = "ip") do={ :if (!($a in $red)) do={ :set fuera ($fuera + 1) } }
}
# Si hay una sesion por WebFig, www no se apaga (te cortaria)
:if ([:len [/user/active/find via="web"]] > 0) do={
  /ip/service/disable telnet,ftp,api
  :put "Ojo: hay una sesion por WebFig. Deje www prendido: apagalo desde WinBox."
} else={ /ip/service/disable telnet,ftp,www,api }
:if ($fuera = 0) do={
  /ip/service/set winbox,ssh available-from=$red
} else={ :put "Ojo: hay sesiones desde fuera de la red de gestion. No limite winbox ni ssh." }
# MAC server y descubrimiento: solo hacia la lista LAN, si existe
:if ([:len [/interface/list/member/find list=LAN]] > 0) do={
  /tool/mac-server/set allowed-interface-list=LAN
  /tool/mac-server/mac-winbox/set allowed-interface-list=LAN
  /ip/neighbor/discovery-settings/set discover-interface-list=LAN
} else={ :put "Ojo: la lista LAN no existe o esta vacia. No toque MAC server ni descubrimiento." }
/tool/bandwidth-server/set enabled=no
/ip/socks/set enabled=no
/ip/proxy/set enabled=no
/ip/upnp/set enabled=no
:put "== Auditoria de equipo heredado (lo normal es que esto este vacio) =="
/system/scheduler/print
/system/script/print
/ip/socks/print
/interface/l2tp-client/print
/ip/firewall/filter/print where dst-port~"5678"
:put "Listo: servicios cerrados y gestion limitada. Verifica con /ip/service/print"
}

# IES Training - MikroTik - Input y forward: reglas de obra (leccion 4)
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
# Requiere el firewall por defecto. No borra reglas existentes.
{
:local oficina "{{OFICINA_IP}}"
:local nvr "{{NVR_IP}}"
:local nube "{{NUBE_NVR}}"
:local camaras "{{CAMARAS}}"
:local drop [/ip/firewall/filter/find chain=input comment="defconf: drop all not coming from LAN"]
:if ([:len $drop] = 0) do={ :error "No encuentro el drop de la defconf: revisa el firewall a mano" }
# 1. La oficina en la lista admins
:if ([:len [/ip/firewall/address-list/find list=admins address=$oficina]] = 0) do={
  /ip/firewall/address-list/add list=admins address=$oficina comment="ies-admins" }
# 2. Gestion desde WAN: cadena propia; admins entra, el resto queda en el log
:if ([:len [/ip/firewall/filter/find comment="ies-gestion-wan"]] = 0) do={
  /ip/firewall/filter/add chain=gestion-wan src-address-list=admins action=accept comment="ies-gestion-wan-admins"
  /ip/firewall/filter/add chain=gestion-wan action=drop log=yes log-prefix="GESTION-WAN" comment="ies-gestion-wan-resto"
  /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=tcp dst-port=22,8291 action=jump jump-target=gestion-wan comment="ies-gestion-wan" place-before=$drop }
# 3. Listas del NVR y de las camaras
:if ([:len [/ip/firewall/address-list/find list=nube-nvr address=$nube]] = 0) do={
  /ip/firewall/address-list/add list=nube-nvr address=$nube comment="ies-nube-nvr" }
:if ([:len [/ip/firewall/address-list/find list=camaras address=$camaras]] = 0) do={
  /ip/firewall/address-list/add list=camaras address=$camaras comment="ies-camaras" }
# 4. Forward: NVR solo a NTP y a su nube (reject al resto); camaras sin internet
:if ([:len [/ip/firewall/filter/find comment="ies-nvr-ntp"]] = 0) do={
  /ip/firewall/filter/add chain=forward src-address=$nvr out-interface-list=WAN protocol=udp dst-port=123 action=accept comment="ies-nvr-ntp"
  /ip/firewall/filter/add chain=forward src-address=$nvr out-interface-list=WAN dst-address-list=nube-nvr action=accept comment="ies-nvr-nube"
  /ip/firewall/filter/add chain=forward src-address=$nvr out-interface-list=WAN action=reject reject-with=icmp-admin-prohibited comment="ies-nvr-resto"
  /ip/firewall/filter/add chain=forward src-address-list=camaras out-interface-list=WAN action=drop comment="ies-camaras-sin-internet" }
# Si ya hay un drop final de zonas (leccion 36), estas reglas van arriba de el
:local fin [/ip/firewall/filter/find comment="ies-zona-fin"]
:if ([:len $fin] > 0) do={
  :foreach c in={"ies-nvr-ntp";"ies-nvr-nube";"ies-nvr-resto";"ies-camaras-sin-internet"} do={
    /ip/firewall/filter/move [/ip/firewall/filter/find comment=$c] destination=$fin } }
:put "Listo: admins, cadena gestion-wan, salida del NVR y camaras sin internet."
:put "Verifica con: /ip/firewall/filter/print stats where comment~\"ies-\""
}

# IES Training - MikroTik - Zonas con interface lists (leccion 36)
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
# Requiere el firewall por defecto. El drop final queda en ensayo: solo log.
{
:local zonas {"GESTION"="{{IF_GESTION}}";"ADMIN"="{{IF_ADMIN}}";"CCTV"="{{IF_CCTV}}";"ACCESOS"="{{IF_ACCESOS}}";"INVITADOS"="{{IF_INVITADOS}}";"VPN"="{{IF_VPN}}"}
:local nvr "{{NVR_IP}}"
:local vpn "{{PUERTO_VPN}}"
:local drop [/ip/firewall/filter/find chain=input comment="defconf: drop all not coming from LAN"]
:if ([:len $drop] = 0) do={ :error "No encuentro el drop de la defconf: revisa el firewall a mano" }
# 1. Una lista por zona, con su interfaz si existe
:foreach z,i in=$zonas do={
  :if ([:len [/interface/list/find name=$z]] = 0) do={ /interface/list/add name=$z comment="ies-zona" }
  :if ([:len [/interface/find name=$i]] = 0) do={ :put ("Ojo: no existe " . $i . ", la zona " . $z . " queda vacia") } else={
    :if ([:len [/interface/list/member/find list=$z interface=$i]] = 0) do={ /interface/list/member/add list=$z interface=$i comment="ies-zona" } } }
# 2. Compuestas: VPN cuenta como gestion; SISTEMAS y CLIENTES
/interface/list/set [find name=GESTION] include=VPN
:if ([:len [/interface/list/find name=SISTEMAS]] = 0) do={ /interface/list/add name=SISTEMAS include=CCTV,ACCESOS comment="ies-zona" }
:if ([:len [/interface/list/find name=CLIENTES]] = 0) do={ /interface/list/add name=CLIENTES include=ADMIN,CCTV,ACCESOS,INVITADOS comment="ies-zona" }
# 3. Input por zona, arriba del drop de fabrica (solo accepts: no corta a nadie)
:if ([:len [/ip/firewall/filter/find comment="ies-zona-in-gestion"]] = 0) do={
  /ip/firewall/filter/add chain=input in-interface-list=GESTION action=accept comment="ies-zona-in-gestion" place-before=$drop
  /ip/firewall/filter/add chain=input in-interface-list=CLIENTES protocol=udp dst-port=53,67 action=accept comment="ies-zona-in-dns-dhcp" place-before=$drop
  /ip/firewall/filter/add chain=input in-interface-list=CLIENTES protocol=tcp dst-port=53 action=accept comment="ies-zona-in-dns-tcp" place-before=$drop
  /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=udp dst-port=$vpn action=accept comment="ies-zona-in-tunel" place-before=$drop }
# 4. Forward: primero el renglon final (ensayo), despues un accept por casillero
:if ([:len [/ip/firewall/filter/find comment="ies-zona-fin"]] = 0) do={
  /ip/firewall/filter/add chain=forward action=log log-prefix="ZONA-ENSAYO" comment="ies-zona-fin" }
:local fin [/ip/firewall/filter/find comment="ies-zona-fin"]
:if ([:len [/ip/firewall/filter/find comment="ies-zona-gestion"]] = 0) do={
  /ip/firewall/filter/add chain=forward in-interface-list=GESTION action=accept comment="ies-zona-gestion" place-before=$fin
  /ip/firewall/filter/add chain=forward in-interface-list=ADMIN out-interface-list=WAN action=accept comment="ies-zona-admin-wan" place-before=$fin
  /ip/firewall/filter/add chain=forward in-interface-list=INVITADOS out-interface-list=WAN action=accept comment="ies-zona-invitados-wan" place-before=$fin
  /ip/firewall/filter/add chain=forward in-interface-list=ADMIN out-interface-list=CCTV dst-address=$nvr protocol=tcp dst-port=80,443,8000 action=accept comment="ies-zona-admin-nvr" place-before=$fin
  /ip/firewall/filter/add chain=forward in-interface-list=SISTEMAS out-interface-list=WAN protocol=udp dst-port=123 action=accept comment="ies-zona-sistemas-ntp" place-before=$fin
  /ip/firewall/filter/add chain=forward in-interface-list=WAN connection-nat-state=dstnat action=accept comment="ies-zona-publicado" place-before=$fin }
# Cuando el log ZONA-ENSAYO muestre solo lo que esperabas, pasalo a drop:
# /ip/firewall/filter/set [find comment="ies-zona-fin"] action=drop log=yes log-prefix="ZONA-DROP"
:put "Listo: zonas, compuestas, input por zona y forward por par de zonas (final en ensayo)."
:put "Verifica con: /interface/list/member/print y /ip/firewall/filter/print stats where comment~\"ies-zona\""
}

# IES Training - MikroTik - Reglas de proteccion (leccion 33)
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
# Requiere el firewall por defecto (defconf). No borra ni mueve reglas existentes.
{
:local admin "{{ADMIN_IP}}"
:local abrirSsh "{{ABRIR_SSH_WAN}}"
:local drop [/ip/firewall/filter/find chain=input comment="defconf: drop all not coming from LAN"]
:if ([:len $drop] = 0) do={ :error "No encuentro el drop de la defconf: revisa el firewall a mano" }
# 1. Lista admins (se usa antes de cualquier drop)
:if ([:len [/ip/firewall/address-list/find list=admins address=$admin]] = 0) do={
  /ip/firewall/address-list/add list=admins address=$admin comment="ies-admins" }
# 2. Ping desde WAN limitado a 5 por segundo, arriba del accept ICMP de fabrica
:local icmp [/ip/firewall/filter/find chain=input comment="defconf: accept ICMP"]
:if (([:len $icmp] > 0) && ([:len [/ip/firewall/filter/find comment="ies-ping-wan-limitado"]] = 0)) do={
  /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=icmp icmp-options=8:0 limit=5,10:packet action=accept comment="ies-ping-wan-limitado" place-before=$icmp
  /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=icmp icmp-options=8:0 action=drop comment="ies-ping-wan-excedido" place-before=$icmp }
# 3. DNS: el 53 no se atiende desde WAN (arriba de todo; no afecta a la LAN)
:local arriba [/ip/firewall/filter/find chain=input comment="defconf: accept established,related,untracked"]
:if ([:len $arriba] = 0) do={ :set arriba $drop }
:foreach p in={"udp";"tcp"} do={
  :if ([:len [/ip/firewall/filter/find comment=("ies-dns-wan-" . $p)]] = 0) do={
    /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=$p dst-port=53 action=drop comment=("ies-dns-wan-" . $p) place-before=$arriba } }
# 4. Solo si SSH tiene que quedar abierto a WAN: admins primero y listas por etapas
:if (($abrirSsh = "si") && ([:len [/ip/firewall/filter/find comment="ies-ssh-admins"]] = 0)) do={
  /ip/firewall/filter/add chain=input protocol=tcp dst-port=22 in-interface-list=WAN src-address-list=admins action=accept comment="ies-ssh-admins" place-before=$drop
  /ip/firewall/filter/add chain=input protocol=tcp dst-port=22 connection-state=new in-interface-list=WAN src-address-list=connection3 action=add-src-to-address-list address-list=bruteforce_blacklist address-list-timeout=1d comment="ies-ssh-lista-negra" place-before=$drop
  /ip/firewall/filter/add chain=input protocol=tcp dst-port=22 connection-state=new in-interface-list=WAN src-address-list=connection2 action=add-src-to-address-list address-list=connection3 address-list-timeout=1h comment="ies-ssh-tercera" place-before=$drop
  /ip/firewall/filter/add chain=input protocol=tcp dst-port=22 connection-state=new in-interface-list=WAN src-address-list=connection1 action=add-src-to-address-list address-list=connection2 address-list-timeout=15m comment="ies-ssh-segunda" place-before=$drop
  /ip/firewall/filter/add chain=input protocol=tcp dst-port=22 connection-state=new in-interface-list=WAN action=add-src-to-address-list address-list=connection1 address-list-timeout=5m comment="ies-ssh-primera" place-before=$drop
  /ip/firewall/filter/add chain=input protocol=tcp dst-port=22 in-interface-list=WAN src-address-list=!bruteforce_blacklist action=accept comment="ies-ssh-aceptar" place-before=$drop
  /ip/firewall/filter/add chain=input protocol=tcp dst-port=22 in-interface-list=WAN action=drop comment="ies-ssh-drop-lista-negra" place-before=$drop }
:put "Listo: admins, ping de WAN limitado y 53 cerrado desde WAN. Verifica con /ip/firewall/filter/print stats where comment~\"ies-\""
}

# IES Training - MikroTik - L30 - DNS del router
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local dns1 "{{DNS1}}"
:local dns2 "{{DNS2}}"
:local nvrname "{{NOMBRE_NVR}}"
:local nvrip "{{IP_NVR}}"
# 1. Primero el candado: el 53 cerrado desde la WAN
:local defconf [:len [/ip/firewall/filter/find comment="defconf: drop all not coming from LAN"]]
:if ($defconf = 0) do={
  :if ([:len [/interface/list/find name=WAN]] = 0) do={ :error "No existe la lista WAN: crearla antes de seguir." }
  :foreach p in={"udp";"tcp"} do={
    :if ([:len [/ip/firewall/filter/find comment=("ies-dns-wan-" . $p)]] = 0) do={
      :if ([:len [/ip/firewall/filter/find]] > 0) do={
        /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=$p dst-port=53 action=drop comment=("ies-dns-wan-" . $p) place-before=[:pick [/ip/firewall/filter/find] 0]
      } else={
        /ip/firewall/filter/add chain=input in-interface-list=WAN protocol=$p dst-port=53 action=drop comment=("ies-dns-wan-" . $p)
      }
    }
  }
  :put "Sin regla de fabrica: agregue drop del 53 UDP y TCP desde la WAN."
} else={ :put "Esta la regla de fabrica: el 53 ya esta cerrado desde la WAN." }
# 2. Servidores y DNS para la LAN
/ip/dns/set servers=($dns1 . "," . $dns2) allow-remote-requests=yes
# 3. Nombre local del NVR (si existe, se actualiza)
:local e [/ip/dns/static/find name=$nvrname]
:if ([:len $e] = 0) do={
  /ip/dns/static/add name=$nvrname address=$nvrip comment="ies-nvr-dns"
} else={ /ip/dns/static/set $e address=$nvrip }
/ip/dns/cache/flush
# 4. DoH (opcional): sin respaldo si el servicio se cae. Descomentar y completar:
# /ip/dns/set use-doh-server="<URL-DoH>" verify-doh-cert=yes
:do { :put ("Prueba: mikrotik.com = " . [:resolve mikrotik.com]) } on-error={ :put "Ojo: no resuelve. Revisar servidores y salida a internet." }
:put ("Listo: DNS " . $dns1 . " y " . $dns2 . ", " . $nvrname . " = " . $nvrip . ". Verifica con /ip/dns/print")
}

# IES Training - MikroTik - L31 - DNS transparente
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local exc "{{EXCEPCION}}"
:local lan "{{LISTA_LAN}}"
# Sin resolver para la LAN, redirigir dejaria a todos sin nombres
:if (![/ip/dns/get allow-remote-requests]) do={ :error "allow-remote-requests esta en no: configurar el DNS del router primero (leccion de DNS)." }
:if ([:len [/interface/list/find name=$lan]] = 0) do={ :error ("No existe la lista " . $lan) }
# 1. Excepciones
:if ([:len [/ip/firewall/address-list/find list=dns-libre address=$exc]] = 0) do={
  /ip/firewall/address-list/add list=dns-libre address=$exc comment="ies-dns-libre"
}
# 2. Redireccion UDP y TCP 53 al router
:foreach p in={"udp";"tcp"} do={
  :if ([:len [/ip/firewall/nat/find comment=("ies-dns-transparente-" . $p)]] = 0) do={
    /ip/firewall/nat/add chain=dstnat in-interface-list=$lan src-address-list=!dns-libre dst-address-type=!local protocol=$p dst-port=53 action=redirect to-ports=53 comment=("ies-dns-transparente-" . $p)
  }
}
# 3. Firefox: no prender DoH por su cuenta
:if ([:len [/ip/dns/static/find name="use-application-dns.net"]] = 0) do={
  /ip/dns/static/add name=use-application-dns.net type=NXDOMAIN comment="ies-canario-firefox"
}
# 4. DNS sobre TLS (853): reject para que vuelvan al 53
:if ([:len [/ip/firewall/filter/find comment="ies-sin-dot"]] = 0) do={
  /ip/firewall/filter/add chain=forward in-interface-list=$lan protocol=tcp dst-port=853 action=reject reject-with=icmp-admin-prohibited comment="ies-sin-dot"
}
:put ("Listo: 53 de " . $lan . " redirigido al router, excepcion " . $exc . ". Verifica con /ip/firewall/nat/print stats where comment~\"ies-dns\"")
}

# IES Training - MikroTik - L32 - Adlist y bloqueo de un sitio
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local cache [:tonum "{{CACHE_KIB}}"]
:local sitio "{{SITIO}}"
:local url "{{URL_ADLIST}}"
# 1. Version: adlist existe desde 7.15
:local v [/system/resource/get version]
:local p [:find $v "."]
:local mayor [:tonum [:pick $v 0 $p]]
:local resto [:pick $v ($p + 1) [:len $v]]
:local fin [:find $resto "."]
:if ([:typeof $fin] = "nil") do={ :set fin [:find $resto " "] }
:local menor [:tonum [:pick $resto 0 $fin]]
:local conadlist (($mayor > 7) or (($mayor = 7) and ($menor >= 15)))
:put ("RouterOS " . $v . " en " . [/system/resource/get architecture-name])
# 2. Cache: solo se sube, nunca se baja
:if ([/ip/dns/get cache-size] < $cache) do={ /ip/dns/set cache-size=$cache }
# 3. Adlist por URL (si la completaste y la version la soporta)
:if (($url != "") and $conadlist) do={
  :if ([:len [/ip/dns/adlist/find url=$url]] = 0) do={ /ip/dns/adlist/add url=$url }
} else={ :if (!$conadlist) do={ :put "Ojo: esta version no tiene adlist. Actualizar a 7.15 o mas." } }
# 4. Sitio entero con subdominios
:if ([:len [/ip/dns/static/find name=$sitio type=NXDOMAIN]] = 0) do={
  /ip/dns/static/add name=$sitio type=NXDOMAIN match-subdomain=yes comment="ies-bloqueo-sitio"
}
/ip/dns/cache/flush
:if ($conadlist) do={ /ip/dns/adlist/print }
:put ("Listo: " . $sitio . " bloqueado con subdominios, cache " . [/ip/dns/get cache-size] . " KiB. Verifica con nslookup " . $sitio . " 192.168.88.1")
}

# IES Training - MikroTik - L9 - Nombre, no puerta
# Solo diagnostico. El nombre DDNS no abre ningun acceso.
{
:local lista "{{LISTA_WAN}}"
/ip/cloud/set ddns-enabled=yes
/ip/cloud/force-update
:delay 8s
:local pub [:tostr [/ip/cloud/get public-address]]
:put ("dns-name: " . [/ip/cloud/get dns-name])
:put ("public-address: " . $pub . "  (status: " . [/ip/cloud/get status] . ")")
:local caso "sin WAN con IP"
:foreach m in=[/interface/list/member/find list=$lista] do={
  :local i [/interface/list/member/get $m interface]
  :foreach a in=[/ip/address/find interface=$i] do={
    :local d [/ip/address/get $a address]
    :local ip [:toip [:pick $d 0 [:find $d "/"]]]
    :put ("IP de " . $i . ": " . $ip)
    :if ([:tostr $ip] = $pub) do={ :set caso "IP publica directa: se puede publicar con cuidado (leccion 10)" } else={
      :if ($ip in 100.64.0.0/10) do={ :set caso "CGNAT: sin port forwarding; tunel saliente o Back To Home" } else={
        :if ($caso = "sin WAN con IP") do={ :set caso "NAT del modem: modo bridge o reenvio tambien en el modem" }
      }
    }
  }
}
:put ("Listo: " . $caso . ". Verifica con /ip/cloud/print")
# Si no vas a usar el nombre, como sugiere la guia de seguridad:
# /ip/cloud/set ddns-enabled=auto update-time=no
}

# IES Training - MikroTik - L8 - Tunel de gestion
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
{
:local wg "{{WG}}"
:local puerto {{PUERTO}}
:local pk "{{PEER_CLAVE_PUBLICA}}"
# 1. Interfaz y direccion
:if ([:len [/interface/wireguard/find name=$wg]] = 0) do={
  /interface/wireguard/add name=$wg listen-port=$puerto comment="ies-wireguard"
}
:if ([:len [/ip/address/find comment="ies-ip-tunel"]] = 0) do={
  /ip/address/add address={{IP_TUNEL}} interface=$wg comment="ies-ip-tunel"
}
# 2. Peer del tecnico (solo si pegaste una clave real)
:if ($pk = "PEGAR-CLAVE-PUBLICA-DE-LA-NOTEBOOK") do={
  :put "Falta la clave publica de la notebook: no agregue el peer."
} else={
  :if ([:len [/interface/wireguard/peers/find public-key=$pk]] = 0) do={
    /interface/wireguard/peers/add interface=$wg name="{{PEER}}" public-key=$pk allowed-address={{PEER_IP}} comment="ies-peer"
  }
}
# 3. Firewall: arriba del drop de fabrica, si existe
:local drop [/ip/firewall/filter/find comment="defconf: drop all not coming from LAN"]
:if ([:len [/ip/firewall/filter/find comment="ies-wireguard"]] = 0) do={
  /ip/firewall/filter/add chain=input protocol=udp dst-port=$puerto action=accept comment="ies-wireguard"
  :if ([:len $drop] > 0) do={ /ip/firewall/filter/move [find comment="ies-wireguard"] destination=[:pick $drop 0] }
}
:if ([:len [/ip/firewall/filter/find comment="ies-winbox-tunel"]] = 0) do={
  /ip/firewall/filter/add chain=input in-interface=$wg protocol=tcp dst-port=8291 action=accept comment="ies-winbox-tunel"
  :if ([:len $drop] > 0) do={ /ip/firewall/filter/move [find comment="ies-winbox-tunel"] destination=[:pick $drop 0] }
}
:if ([:len $drop] = 0) do={ :put "Ojo: no encontre el drop de fabrica. Revisa el orden de input a mano." }
:put ("Clave publica del router: " . [/interface/wireguard/get [find name=$wg] public-key])
:put "Listo: tunel creado. Verifica last-handshake con /interface/wireguard/peers/print"
}

# IES Training - MikroTik - Leccion 19: Back To Home
# Solo CPU ARM, ARM64 o TILE con RouterOS 7.12 o posterior. Nunca revoques para dar una baja.
{
  :local usuario "{{USUARIO}}"
  :local equipo "{{DISPOSITIVO}}"
  # 1. Arquitectura antes de prometerlo
  :local arch [/system/resource/get architecture-name]
  :if (!($arch = "arm" || $arch = "arm64" || $arch = "tile")) do={ :error ("Back To Home no corre en " . $arch . ": usa un concentrador (leccion 20)") }
  :put ("Arquitectura " . $arch . " | RouterOS " . [/system/resource/get version])
  # Activar y esperar vpn-status: running (hasta 30 s)
  /ip/cloud/set back-to-home-vpn=enabled
  :local i 0
  :while ((!([:tostr [/ip/cloud/get vpn-status]] ~ "running")) && ($i < 15)) do={ :delay 2s; :set i ($i + 1) }
  :if (!([:tostr [/ip/cloud/get vpn-status]] ~ "running")) do={ :error "Back To Home no llego a running: mira /ip/cloud/print" }
  # 2. Usuario del dispositivo, con LAN acotada y vencimiento
  :local u [/ip/cloud/back-to-home-user/find name=$usuario]
  :if ([:len $u] = 0) do={
    /ip/cloud/back-to-home-user/add name=$usuario allow-lan=yes client-allowed-address={{LAN}} expires={{VENCE}} comment=("ies-" . $equipo)
  } else={
    /ip/cloud/back-to-home-user/set $u allow-lan=yes client-allowed-address={{LAN}}
    :put ("El usuario " . $usuario . " ya existia: el vencimiento no se cambia (para otro, borralo y crealo de nuevo).")
  }
  # 5. La restriccion depende de la lista LAN
  :if ([:len [/interface/list/member/find list=LAN]] = 0) do={ :put "La lista LAN esta vacia: agrega tus redes locales antes de dar acceso." }
  :put ("vpn-dns-name: " . [:tostr [/ip/cloud/get vpn-dns-name]] . " | relay: " . [:tostr [/ip/cloud/get vpn-relay-ipv4-status]])
  # 3. QR y configuracion para la app WireGuard o Back To Home
  /ip/cloud/back-to-home-user/show-client-config [find name=$usuario]
  :put ("Listo: Back To Home activo y usuario " . $usuario . " con LAN {{LAN}}, vence {{VENCE}}.")
  :put ("Baja de esa persona: /ip/cloud/back-to-home-user/remove [find name=" . $usuario . "]")
}

# IES Training - MikroTik - Leccion 20: Concentrador CHR (hub WireGuard)
# Va en el CHR. Primera vez como admin: crea tu usuario y frena. Entra con el y pegalo de nuevo.
{
  :local usuario "{{USUARIO}}"
  :local oficina {{OFICINA}}
  :local tunel {{TUNEL_RED}}
  :local clave "{{PEER_CLAVE}}"
  # 1. Usuario propio; admin se deshabilita solo cuando no hay una sesion de admin abierta
  :if ([:len [/user/find name=$usuario]] = 0) do={ /user/add name=$usuario group=full password="{{CLAVE}}" comment="ies-hub" }
  :if ([:len [/user/active/find name="admin"]] > 0) do={ :error ("Sesion de admin abierta: entra como " . $usuario . " y volve a pegar el script") }
  /user/disable [find name="admin"]
  /ip/service/disable telnet,ftp,www,api,api-ssl
  /ip/neighbor/discovery-settings/set discover-interface-list=none
  /ip/dns/set allow-remote-requests=no
  # Desde donde entras: lo que puede cortarte se aplica solo si es la oficina o el tunel
  :local desde false
  :foreach s in=[/user/active/find name=$usuario] do={
    :local a [:toip [:tostr [/user/active/get $s address]]]
    :if (([:typeof $a] = "ip") && (($a in $oficina) || ($a in $tunel))) do={ :set desde true }
  }
  # 4. Hub WireGuard (antes del firewall: la regla del tunel usa wg-hub)
  :if ([:len [/interface/wireguard/find name=wg-hub]] = 0) do={ /interface/wireguard/add name=wg-hub listen-port={{PUERTO}} comment="ies-hub" }
  :if ([:len [/ip/address/find interface=wg-hub]] = 0) do={ /ip/address/add address={{HUB_IP}} interface=wg-hub comment="ies-hub" }
  :if ([:len $clave] = 44) do={
    :if ([:len [/interface/wireguard/peers/find interface=wg-hub name="{{PEER_NOMBRE}}"]] = 0) do={ /interface/wireguard/peers/add interface=wg-hub name="{{PEER_NOMBRE}}" public-key=$clave allowed-address={{PEER_IP}} comment="ies-hub" }
  } else={ :put "Sin clave publica real del sitio: el peer no se crea. Cargala en PEER_CLAVE y volve a pegar." }
  # 2. Lista WAN y firewall de input, en orden y una sola vez cada regla
  :if ([:len [/interface/list/find name=WAN]] = 0) do={ /interface/list/add name=WAN comment="ies-hub" }
  :if ([:len [/interface/list/member/find list=WAN interface={{WAN}}]] = 0) do={ /interface/list/member/add list=WAN interface={{WAN}} comment="ies-hub" }
  :if ([:len [/ip/firewall/filter/find comment="ies-established"]] = 0) do={ /ip/firewall/filter/add chain=input connection-state=established,related action=accept comment="ies-established" }
  :if ([:len [/ip/firewall/filter/find comment="ies-wireguard hub"]] = 0) do={ /ip/firewall/filter/add chain=input protocol=udp dst-port={{PUERTO}} action=accept comment="ies-wireguard hub" }
  :if ([:len [/ip/firewall/filter/find comment="ies-gestion oficina"]] = 0) do={ /ip/firewall/filter/add chain=input src-address=$oficina protocol=tcp dst-port=22,8291 action=accept comment="ies-gestion oficina" }
  :if ([:len [/ip/firewall/filter/find comment="ies-icmp"]] = 0) do={ /ip/firewall/filter/add chain=input protocol=icmp action=accept comment="ies-icmp" }
  :if ([:len [/ip/firewall/filter/find comment="ies-winbox por tunel"]] = 0) do={ /ip/firewall/filter/add chain=input in-interface=wg-hub protocol=tcp dst-port=8291 action=accept comment="ies-winbox por tunel" }
  :if ($desde) do={
    :if ([:len [/ip/firewall/filter/find comment="ies-drop resto WAN"]] = 0) do={ /ip/firewall/filter/add chain=input in-interface-list=WAN action=drop comment="ies-drop resto WAN" }
    /ip/service/set winbox,ssh available-from={{OFICINA}},{{TUNEL_RED}}
    /tool/mac-server/set allowed-interface-list=none
    /tool/mac-server/mac-winbox/set allowed-interface-list=none
  } else={ :put "No entras desde la oficina ni por el tunel: el drop de WAN, available-from y el MAC server quedan sin tocar. Pegalo desde ahi." }
  # 3. Licencia (prueba de 60 dias: /system/license/renew con tu cuenta)
  /system/license/print
  :put ("Clave publica del hub, para el sitio: " . [/interface/wireguard/get wg-hub public-key])
  :put "Listo: CHR endurecido y wg-hub escuchando. Verifica: /ip/firewall/filter/print ; /interface/wireguard/peers/print"
}

# IES Training - MikroTik - L10 - NVR con criterio
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X).
# Primera opcion siempre: VPN (leccion 8). Esto es para cuando no queda otra.
{
:local nvr "{{NVR_IP}}"
:local puerto "{{PUERTO}}"
:local lista "{{LISTA}}"
:if ($puerto = "80" || $puerto = "443" || $puerto = "8291") do={ :error "Ese puerto es del propio router: no se publica." }
# 1. Origen permitido, con fecha de revision
:if ([:len [/ip/firewall/address-list/find list=$lista address={{ORIGEN}}]] = 0) do={
  /ip/firewall/address-list/add list=$lista address={{ORIGEN}} comment="ies-nvr origen, revisar {{REVISAR}}"
}
# 2. Un solo dst-nat: por WAN, un puerto, solo la lista
:if ([:len [/ip/firewall/nat/find comment="ies-nvr"]] = 0) do={
  /ip/firewall/nat/add chain=dstnat in-interface-list=WAN protocol=tcp dst-port=$puerto src-address-list=$lista action=dst-nat to-addresses=$nvr to-ports=$puerto comment="ies-nvr"
} else={
  /ip/firewall/nat/set [find comment="ies-nvr"] dst-port=$puerto src-address-list=$lista to-addresses=$nvr to-ports=$puerto
}
# 3. Conexiones viejas fuera, para que la regla nueva aplique
:local re (":" . $puerto)
/ip/firewall/connection/remove [find where dst-address~$re]
# 4. Hairpin: solo si desde la LAN entran por la IP publica. Ademas, en el
# dst-nat, cambiar in-interface-list=WAN por dst-address-type=local dst-address=!192.168.88.1
# /ip/firewall/nat/add chain=srcnat src-address=192.168.88.0/24 dst-address={{NVR_IP}} protocol=tcp dst-port={{PUERTO}} out-interface=bridge action=masquerade comment="ies-nvr-hairpin"
:put ("Listo: TCP " . $puerto . " hacia " . $nvr . " solo para la lista " . $lista . ". Verifica con /ip/firewall/nat/print stats where comment=\"ies-nvr\"")
}

# IES Training - MikroTik - Leccion 24: Port forwarding de un NVR, solo para origenes conocidos
# Probalo primero en un equipo de banco y en Safe Mode (Ctrl+X). Primera opcion para entrar: VPN.
{
  :local wan "{{WAN}}"
  :local nvr "{{NVR_NOMBRE}}"
  :local ip [:toip "{{NVR_IP}}"]
  :local lista "{{LISTA}}"
  :local extR "{{PUERTO_EXT_RTSP}}"
  :local intR "{{PUERTO_INT_RTSP}}"
  /export file=ies-antes-port-forwarding
  # 1. La IP del WAN dice si se puede: doble NAT o CGNAT
  :foreach a in=[/ip/address/find interface=$wan] do={
    :local d [:tostr [/ip/address/get $a address]]
    :local w [:toip [:pick $d 0 [:find $d "/"]]]
    :if ($w in 100.64.0.0/10) do={ :put "WAN en 100.64.0.0/10: CGNAT, no hay port forwarding posible (lecciones 19 y 20)." }
    :if (($w in 10.0.0.0/8) || ($w in 172.16.0.0/12) || ($w in 192.168.0.0/16)) do={ :put "WAN privada: doble NAT. ONT en bridge (leccion 15) o reenvio tambien en el modem." }
  }
  # 2. Origenes permitidos (se agregan una sola vez)
  :foreach o in=[:toarray "{{ORIGENES}}"] do={
    :if ([:len [/ip/firewall/address-list/find list=$lista address=$o]] = 0) do={ /ip/firewall/address-list/add list=$lista address=$o comment="ies-origen NVR, revisar {{REVISAR}}" }
  }
  # 3. dst-nat atado a la WAN y a la lista; si ya estaba, se reemplaza
  /ip/firewall/nat/remove [find chain=dstnat comment~("^ies-" . $nvr . " SDK ")]
  /ip/firewall/nat/add chain=dstnat in-interface-list=WAN src-address-list=$lista protocol=tcp dst-port={{PUERTO_EXT}} action=dst-nat to-addresses=$ip to-ports={{PUERTO_INT}} comment=("ies-" . $nvr . " SDK {{PUERTO_EXT}}>{{PUERTO_INT}}")
  :if ([:len $extR] > 0) do={
    /ip/firewall/nat/remove [find chain=dstnat comment~("^ies-" . $nvr . " RTSP ")]
    /ip/firewall/nat/add chain=dstnat in-interface-list=WAN src-address-list=$lista protocol=tcp dst-port=$extR action=dst-nat to-addresses=$ip to-ports=$intR comment=("ies-" . $nvr . " RTSP " . $extR . ">" . $intR)
  }
  # 4. Forward: la regla de fabrica ya deja pasar lo dst-nateado
  :if ([:len [/ip/firewall/filter/find comment~"not DSTNATed"]] = 0) do={ :put "No esta la regla de fabrica not DSTNATed: agrega el accept de publicados arriba de tu drop de forward (leccion 4)." }
  # 5. Conexiones viejas afuera
  /ip/firewall/connection/remove [find dst-address~":{{PUERTO_EXT}}"]
  :if ([:len $extR] > 0) do={ /ip/firewall/connection/remove [find dst-address~(":" . $extR)] }
  # 6. Contadores: si no suben al probar, el paquete no llega o el origen no esta en la lista
  /ip/firewall/nat/print stats where comment~("^ies-" . $nvr)
  :put ("Listo: " . $nvr . " publicado en {{PUERTO_EXT}} hacia " . $ip . ":{{PUERTO_INT}} solo para la lista " . $lista . ".")
  :put "Verifica desde la oficina: Test-NetConnection <IP publica> -Port {{PUERTO_EXT}} y mira que suba el contador."
}

# IES Training - MikroTik - Leccion 21: Servidor L2TP con IPsec obligatorio
# Probalo primero en un equipo de banco. Pensado para la configuracion por defecto.
{
  :local drop [/ip/firewall/filter/find comment="defconf: drop all not coming from LAN"]
  :if ([:len $drop] = 0) do={ :error "No esta el drop de fabrica en input: ubica las reglas a mano (leccion 4). No se cambio nada." }
  # 1. Pool, perfil y servidor
  :if ([:len [/ip/pool/find name=pool-l2tp]] = 0) do={ /ip/pool/add name=pool-l2tp ranges={{POOL}} comment="ies-l2tp" } else={ /ip/pool/set [find name=pool-l2tp] ranges={{POOL}} }
  :if ([:len [/ppp/profile/find name=perfil-l2tp]] = 0) do={
    /ppp/profile/add name=perfil-l2tp local-address={{IP_LOCAL}} remote-address=pool-l2tp dns-server={{DNS}} comment="ies-l2tp"
  } else={ /ppp/profile/set [find name=perfil-l2tp] local-address={{IP_LOCAL}} remote-address=pool-l2tp dns-server={{DNS}} }
  /interface/l2tp-server/server/set enabled=yes use-ipsec=required ipsec-secret="{{SECRETO_IPSEC}}" default-profile=perfil-l2tp
  # 2. Un usuario por persona
  :if ([:len [/ppp/secret/find name="{{USUARIO}}"]] = 0) do={
    /ppp/secret/add name="{{USUARIO}}" password="{{CLAVE}}" service=l2tp profile=perfil-l2tp comment="ies-l2tp"
  } else={ /ppp/secret/set [find name="{{USUARIO}}"] password="{{CLAVE}}" service=l2tp profile=perfil-l2tp }
  # 3. Input, arriba del drop de fabrica
  :if ([:len [/ip/firewall/filter/find comment="ies-L2TP IPsec"]] = 0) do={ /ip/firewall/filter/add chain=input protocol=udp dst-port=500,4500,1701 action=accept comment="ies-L2TP IPsec" place-before=[:pick $drop 0] }
  :if ([:len [/ip/firewall/filter/find comment="ies-ESP"]] = 0) do={ /ip/firewall/filter/add chain=input protocol=ipsec-esp action=accept comment="ies-ESP" place-before=[:pick $drop 0] }
  # 4. Trafico del tunel fuera de FastTrack, si no hay ya un accept in,ipsec activo
  :local ft [/ip/firewall/filter/find action=fasttrack-connection]
  :local hay [:len [/ip/firewall/filter/find chain=forward action=accept ipsec-policy="in,ipsec" disabled=no]]
  :if ($hay = 0 && [:len [/ip/firewall/filter/find comment="ies-IPsec fuera de FastTrack"]] = 0) do={
    :if ([:len $ft] > 0) do={ /ip/firewall/filter/add chain=forward ipsec-policy=in,ipsec action=accept comment="ies-IPsec fuera de FastTrack" place-before=[:pick $ft 0] } else={ /ip/firewall/filter/add chain=forward ipsec-policy=in,ipsec action=accept comment="ies-IPsec fuera de FastTrack" }
  }
  /ip/firewall/filter/print where comment~"^ies-"
  :put "Listo: L2TP con IPsec obligatorio, perfil perfil-l2tp, usuario {{USUARIO}} y UDP 500, 4500, 1701 y ESP en input."
  :put "Verifica: /ip/ipsec/active-peers/print ; /ppp/active/print ; /log/print where topics~\"ipsec|l2tp\""
}

# IES Training - MikroTik - Leccion 22: IPsec sitio a sitio (IKEv2, clave precompartida)
# Primero la tabla firmada por las dos puntas. Fase 1: AES-256, SHA-256, DH 14, 1d. Fase 2: AES-256-CBC, SHA-256, PFS 14, 1h.
{
  :local n "{{NOMBRE}}"
  :local remoto {{PEER_IP}}
  :local redL {{RED_LOCAL}}
  :local redR {{RED_REMOTA}}
  :if ($redL = $redR) do={ :error "Las dos LAN tienen el mismo rango: renumera una antes del tunel" }
  :local drop [/ip/firewall/filter/find comment="defconf: drop all not coming from LAN"]
  :if ([:len $drop] = 0) do={ :error "No esta el drop de fabrica en input: ubica las reglas a mano (leccion 4). No se cambio nada." }
  # 2. Las cinco piezas (profile no tiene comment: se busca por nombre)
  :if ([:len [/ip/ipsec/profile/find name=("perfil-" . $n)]] = 0) do={ /ip/ipsec/profile/add name=("perfil-" . $n) hash-algorithm=sha256 enc-algorithm=aes-256 dh-group=modp2048 lifetime=1d }
  :if ([:len [/ip/ipsec/peer/find name=$n]] = 0) do={ /ip/ipsec/peer/add name=$n address=$remoto profile=("perfil-" . $n) exchange-mode=ike2 comment=("ies-ipsec " . $n) }
  :if ([:len [/ip/ipsec/identity/find peer=$n]] = 0) do={ /ip/ipsec/identity/add peer=$n auth-method=pre-shared-key secret="{{PSK}}" comment=("ies-ipsec " . $n) } else={ /ip/ipsec/identity/set [find peer=$n] secret="{{PSK}}" }
  :if ([:len [/ip/ipsec/proposal/find name=("prop-" . $n)]] = 0) do={ /ip/ipsec/proposal/add name=("prop-" . $n) auth-algorithms=sha256 enc-algorithms=aes-256-cbc pfs-group=modp2048 lifetime=1h comment=("ies-ipsec " . $n) }
  :if ([:len [/ip/ipsec/policy/find peer=$n]] = 0) do={ /ip/ipsec/policy/add peer=$n tunnel=yes src-address=$redL dst-address=$redR proposal=("prop-" . $n) action=encrypt comment=("ies-ipsec " . $n) }
  # 3. Puertos solo desde el otro extremo, arriba del drop
  :if ([:len [/ip/firewall/filter/find comment=("ies-IKE " . $n)]] = 0) do={ /ip/firewall/filter/add chain=input src-address=$remoto protocol=udp dst-port=500,4500 action=accept comment=("ies-IKE " . $n) place-before=[:pick $drop 0] }
  :if ([:len [/ip/firewall/filter/find comment=("ies-ESP " . $n)]] = 0) do={ /ip/firewall/filter/add chain=input src-address=$remoto protocol=ipsec-esp action=accept comment=("ies-ESP " . $n) place-before=[:pick $drop 0] }
  # 4. Bypass de NAT (arriba de todo el NAT) y de FastTrack (arriba del fasttrack)
  :local nat [/ip/firewall/nat/find]
  :if ([:len [/ip/firewall/nat/find comment=("ies-no NAT al tunel " . $n)]] = 0) do={
    :if ([:len $nat] > 0) do={ /ip/firewall/nat/add chain=srcnat src-address=$redL dst-address=$redR action=accept comment=("ies-no NAT al tunel " . $n) place-before=[:pick $nat 0] } else={ /ip/firewall/nat/add chain=srcnat src-address=$redL dst-address=$redR action=accept comment=("ies-no NAT al tunel " . $n) }
  }
  :local ft [/ip/firewall/filter/find action=fasttrack-connection]
  :if ([:len $ft] > 0 && [:len [/ip/firewall/filter/find comment=("ies-tunel fuera de FastTrack " . $n)]] = 0) do={
    /ip/firewall/filter/add chain=forward src-address=$redL dst-address=$redR action=accept comment=("ies-tunel fuera de FastTrack " . $n) place-before=[:pick $ft 0]
    /ip/firewall/filter/add chain=forward src-address=$redR dst-address=$redL action=accept comment=("ies-tunel fuera de FastTrack " . $n) place-before=[:pick $ft 0]
  }
  # 5. Log de IPsec (sin debug), una sola vez
  :local hayLog false
  :foreach l in=[/system/logging/find] do={ :if ([:tostr [/system/logging/get $l topics]] ~ "ipsec") do={ :set hayLog true } }
  :if (!$hayLog) do={ /system/logging/add topics=ipsec,!debug }
  :delay 5s
  /ip/ipsec/active-peers/print
  :put ("ph2-state: " . [/ip/ipsec/policy/get [find peer=$n] ph2-state] . " (established = fase 2 arriba)")
  :put ("Listo: tunel " . $n . " " . $redL . " <-> " . $redR . " con bypass de NAT y FastTrack.")
  :put "Verifica: /ip/ipsec/installed-sa/print ; /log/print where topics~\"ipsec\""
}

# IES Training - MikroTik - Leccion 17: Elegir el canal
# Solo consulta y cambia el canal: no instala nada. Necesita salida a internet por HTTPS.
{
  :local canal "{{CANAL}}"
  :if (!($canal = "long-term" || $canal = "stable" || $canal = "testing" || $canal = "development")) do={ :error "Canal invalido: long-term, stable, testing o development" }
  # 1. Canal y version actuales
  :local antes [/system/package/update/get channel]
  :local inst [/system/package/update/get installed-version]
  :put ("Canal actual: " . $antes . " | instalada: " . $inst)
  # 2. Que ofrece cada canal, sin instalar
  :foreach c in={"long-term";"stable"} do={
    /system/package/update/set channel=$c
    /system/package/update/check-for-updates once
    :delay 5s
    :put ("  " . $c . " ofrece: " . [/system/package/update/get latest-version])
  }
  # 3. Dejar el canal elegido
  /system/package/update/set channel=$canal
  /system/package/update/check-for-updates once
  :delay 5s
  :local ult [/system/package/update/get latest-version]
  :if ([:len $ult] = 0) do={ :put "El servidor no contesto: revisa salida a internet (TCP 443) y repeti." } else={
    :if ($ult = $inst) do={ :put ("Al dia en " . $canal . ": " . $inst) } else={ :put ("En " . $canal . " hay " . $ult . " (instalada " . $inst . "). Si es menor, el canal ofrece bajar. Backup antes (leccion 16).") }
  }
  :if ($canal != "long-term") do={ :put "Ojo: en sitios de clientes, long-term salvo que necesites algo de stable probado en el banco." }
  :put ("Listo: canal " . $canal . " (antes " . $antes . "). Anota canal, version y fecha en el legajo.")
  :put "Verifica: /system/package/update/print"
}
